/*
 * A033158  Begins with (1, 5); avoids 3-term arithmetic progressions.
 * https://oeis.org/A033158
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(1)=1, a(2)=5. For n>2, a(n) is the smallest integer > a(n−1)
 *            such that the set {a(1),…,a(n)} contains no 3‑term arithmetic
 *            progression. The sequence is generated by a greedy algorithm
 * Range:     u8 n <= 38, u16 n <= 1010, u32 n <= 2000, u64 n <= 2000,
 *            u128 n <= 2000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdbool.h>
#include <stdint.h>

/* forward declaration */
static void ensure_a_capacity(idx_t need);
static void ensure_forbidden_capacity(idx_t bits_needed);
static void set_forbidden(idx_t v);
static bool is_forbidden(idx_t v);

/* storage for the computed sequence */
static seq_t *seq_vals = NULL;
static idx_t seq_len   = 0;
static idx_t seq_cap   = 0;

/* storage for forbidden numbers as a bitset */
static uint8_t *forb_bits = NULL;
static idx_t    forb_bits_cap = 0; /* number of bits available */

/* Ensure seq_vals has room for at least ‘need’ elements */
static void ensure_a_capacity(idx_t need)
{
    if (need <= seq_cap) return;
    idx_t new_cap = seq_cap ? seq_cap << 1 : 8;
    while (new_cap < need) new_cap <<= 1;
    seq_vals = (seq_t *)realloc(seq_vals, new_cap * sizeof(seq_t));
    seq_cap = new_cap;
}

/* Ensure forb_bits has at least ‘bits_needed’ bits free (bytes are rounded up) */
static void ensure_forbidden_capacity(idx_t bits_needed)
{
    if (bits_needed <= forb_bits_cap) return;
    idx_t new_cap = forb_bits_cap ? forb_bits_cap << 1 : 64;
    while (new_cap < bits_needed) new_cap <<= 1;
    size_t old_bytes = (forb_bits_cap + 7) >> 3;
    size_t new_bytes = (new_cap    + 7) >> 3;
    forb_bits = (uint8_t *)realloc(forb_bits, new_bytes);
    /* zero the new part */
    for (size_t i = old_bytes; i < new_bytes; ++i) forb_bits[i] = 0;
    forb_bits_cap = new_cap;
}

/* Set bit corresponding to value ‘v’ as forbidden */
static void set_forbidden(idx_t v)
{
    if (v >= forb_bits_cap) ensure_forbidden_capacity(v + 1);
    forb_bits[v >> 3] |= (uint8_t)(1u << (v & 7));
}

/* Query whether value ‘v’ is forbidden */
static bool is_forbidden(idx_t v)
{
    if (v >= forb_bits_cap) return false;
    return (forb_bits[v >> 3] >> (v & 7)) & 1u;
}

/* Main sequence function */
seq_t a(idx_t n)
{
    /* sequence starts at index 1 */
    if (n == 0) return (seq_t)0;   /* undefined for 0, return 0 */

    /* initialise base case if not yet done */
    if (seq_len == 0) {
        ensure_a_capacity(4);
        seq_vals[0] = (seq_t)1;
        seq_vals[1] = (seq_t)5;
        seq_len = 2;

        /* initialise forbidden set with first pair (1,5) */
        ensure_forbidden_capacity(0);
        idx_t t = (idx_t)( (seq_t)2 * seq_vals[1] - seq_vals[0] );
        set_forbidden(t);
    }

    /* generate terms until we have at least n of them */
    while (seq_len < n) {
        seq_t prev    = seq_vals[seq_len-1];
        seq_t cand    = prev + (seq_t)1;
        /* find first candidate not forbidden */
        while (is_forbidden((idx_t)cand)) ++cand;

        /* append candidate to the sequence */
        ensure_a_capacity(seq_len + 1);
        seq_vals[seq_len] = cand;
        /* add new forbidden values produced by pairing candidate with all earlier terms */
        for (idx_t i = 0; i < seq_len; ++i) {
            /* candidate is larger than seq_vals[i] */
            idx_t t = (idx_t)( (seq_t)2 * cand - seq_vals[i] );
            set_forbidden(t);
        }
        ++seq_len;
    }

    return seq_vals[n-1];
}
